class Solution:
    def getMaxLen(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            sign = 1
            for j in range(i, n):
                if nums[j] == 0:
                    break
                if nums[j] < 0:
                    sign = -sign
                if sign > 0:
                    ans = max(ans, j - i + 1)
        return ans

