class Solution:
    def getMaxLen(self, nums: List[int]) -> int:
        def best(seg):
            neg = sum(x < 0 for x in seg)
            if neg % 2 == 0:
                return len(seg)
            first = next(i for i, x in enumerate(seg) if x < 0)
            last = len(seg) - 1 - next(i for i, x in enumerate(reversed(seg)) if x < 0)
            return max(last, len(seg) - 1 - first)
        ans, seg = 0, []
        for x in nums + [0]:
            if x == 0:
                ans = max(ans, best(seg))
                seg = []
            else:
                seg.append(x)
        return ans

