class Solution {
public:
    int getMaxLen(vector<int>& nums) {
        auto best = [](vector<int>& seg) {
            int neg = 0;
            for (int x : seg) neg += x < 0;
            int n = seg.size();
            if (neg % 2 == 0) return n;
            int first = 0, last = n - 1;
            while (seg[first] >= 0) first++;
            while (seg[last] >= 0) last--;
            return max(last, n - 1 - first);
        };
        int ans = 0;
        vector<int> seg;
        for (int x : nums) {
            if (x == 0) {
                ans = max(ans, best(seg));
                seg.clear();
            } else {
                seg.push_back(x);
            }
        }
        ans = max(ans, best(seg));
        return ans;
    }
};

