class Solution {
    public int getMaxLen(int[] nums) {
        int ans = 0, start = 0;
        for (int i = 0; i <= nums.length; i++) {
            if (i == nums.length || nums[i] == 0) {
                ans = Math.max(ans, best(nums, start, i));
                start = i + 1;
            }
        }
        return ans;
    }

    private int best(int[] a, int lo, int hi) {
        int neg = 0;
        for (int i = lo; i < hi; i++) if (a[i] < 0) neg++;
        if (neg % 2 == 0 || lo == hi) return hi - lo;
        int first = lo, last = hi - 1;
        while (a[first] >= 0) first++;
        while (a[last] >= 0) last--;
        return Math.max(last - lo, hi - 1 - first);
    }
}

