        for x in nums:
            if x == 0:
                pos, neg = 0, 0
            elif x > 0:
                pos += 1
                neg = neg + 1 if neg > 0 else 0
            else:
                pos, neg = (neg + 1 if neg > 0 else 0), pos + 1
            ans = max(ans, pos)
        return ans

